  $('#dialog-location').textContent=displayLocation(book);
  $('#dialog-title').textContent=book.title;$('#dialog-author').textContent=book.author;$('#dialog-description').textContent=resolvedMetadata.has(book.id)||descriptions[book.title]?plainDescription(book):t('researching');
  const info=resolvedMetadata.get(book.id);
