  $('#dialog-genre').textContent=genreName(book.genre);$('#dialog-condition').textContent=t(book.condition==='sealed'?'sealedCondition':'usedCondition');
  const isbnFact=$('#dialog-isbn');isbnFact.textContent=book.isbn||(book.candidateIsbn?`${book.candidateIsbn} (${t('candidateIsbn')})`:t('noIsbn'));
